                if g[i][j]!=bg and (i,j) not in used:
                    q=[(i,j)];used.add((i,j));comp={(i,j)}
                    while q:
                        a,b=q.pop()
                        for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                            y=(a+dx,b+dy)
                            if 0<=y[0]<h and 0<=y[1]<w and y not in used and g[y[0]][y[1]]!=bg:
                                used.add(y);comp.add(y);q.append(y)
                    comps.append(sorted(comp))
        rsps={tuple(c):(min(a for a,b in c),max(a for a,b in c)) for c in comps}
        csps={tuple(c):(min(b for a,b in c),max(b for a,b in c)) for c in comps}
        for i in range(h):
            for j in range(w):
                if g[i][j]!=bg: continue
                best=min(comps,key=lambda c:min(max(abs(i-a),abs(j-b)) for a,b in c))
                r0,r1,c0,c1=rsps[tuple(best)],csps[tuple(best)]
                above=any(aa<i and bb==j for aa,bb in best)
                below=any(aa>i and bb==j for aa,bb in best)
                inside=any(r0<i<r1 and c0<j<c1 for aa,bb in best) or any(r0>=i or r1<=i and c0>=j or c1<=j for aa,bb in best)
                # direct relations
                d[(p,i,j)]=dict(i=i,j=j,dist=min(max(abs(i-a),abs(j-b)) for a,b in best),
                                 above=above,below=below,incol=inside,
                                 r0=r0,r1=r1,c0=c0,c1=c1,target=o[i][j]==1)
    return d
