    objs=sorted(comps_of(g,bg),key=lambda o:(max(a for a,b in o),min(b for a,b in o)) if order=='bottomfirst' else -(max(a for a,b in o)))
    # occupied set of final positions
    occ=set()
    sweep=set()   # bg cells swept -> 1
    def try_place(o,dr):
        for a,b in o:
            if dr+a>=h: return False
            if (a+dr,b) in occ: return False
        return True
    for dr in [0,1,-1]:
        pass
    for o in objs:
        rs=[a for a,b in o];cs=[b for a,b in o]
        best=0
        dmax=max(rs)+1-(h)
        rlo=max(a for a,b in o)
        # max possible drop so that all cells land on occupied/floor or stay
        cand=[]
        for dr in range(0,h-max(rs)):
            if try_place(o,dr): cand.append(dr)
        if not cand: cand=[0]
        dr=cand[-1]
        for a,b in o: occ.add((a+dr,b))
        if paint_all or paint_blocked:
            for a,b in o:
                s=set()
                for da in range(1,dr+1):
                    if g[a+da][b]==bg: s.add((a+da,b))
                sweep|=s
    out=[[3]*w for _ in range(h)]
    for o in objs:
        for a,b in o: out[a][0]+=0
    for a,b in sweep: out[a][b]=1
    return out
