def components(g, val=9):
    seen=set(); out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]==val and (i,j) not in seen:
                st=[(i,j)]; comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen or g[a][b]!=val: continue
                    seen.add((a,b)); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<len(g) and 0<=y<len(g[0]): st.append((x,y))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                out.append((min(rs),max(rs),min(cs),max(cs),len(comp)))
    return out
